  "A policy is a set of limits. It only runs on the ACs you attach it to (open an AC › Alert policies). Every AC also has the default policy.": "Kebijakan adalah sekumpulan batas. Kebijakan hanya berjalan pada AC yang Anda pasangi (buka AC › Kebijakan peringatan). Setiap AC juga memiliki kebijakan default.",
