  "Covers ventilation and the usual causes of breakdowns. It is attached to every AC and cannot be detached or edited, but the account owner can switch each rule on or off for your account (all your ACs); members see the rules read-only. Ask HQ if a limit should change.": "Mencakup ventilasi dan penyebab umum kerusakan. Terpasang pada setiap AC dan tidak dapat dilepas atau diubah, tetapi pemilik akun dapat mengaktifkan atau menonaktifkan tiap aturan untuk akun Anda (semua AC Anda); anggota hanya dapat melihat aturan. Hubungi HQ jika suatu batas perlu diubah.",
