  "Each AC has its own control screen; Group control sends one setting to several ACs in a space. Unit membership is managed in HQ’s unit register.": "Setiap AC memiliki layar kontrolnya sendiri; Kontrol grup mengirim satu pengaturan ke beberapa AC di satu ruang. Keanggotaan unit dikelola di register unit HQ.",
