  "Not granted": "Belum diberikan",
  "Granted {when} · used only by {n} location automation · demo location events (no real GPS history).": "Diberikan {when} · hanya dipakai oleh {n} otomasi lokasi · peristiwa lokasi demo (tanpa riwayat GPS nyata).",
  "Granted {when} · used only by {n} location automations · demo location events (no real GPS history).": "Diberikan {when} · hanya dipakai oleh {n} otomasi lokasi · peristiwa lokasi demo (tanpa riwayat GPS nyata).",
  "Withdrawn {when} · {n} location automation was turned off and will not run. Granting consent again does NOT turn them back on automatically — you re-enable each one. Manual control is unaffected.": "Dicabut {when} · {n} otomasi lokasi dinonaktifkan dan tidak akan berjalan. Memberikan persetujuan lagi TIDAK mengaktifkannya kembali secara otomatis — Anda mengaktifkan ulang satu per satu. Kontrol manual tidak terpengaruh.",
  "Withdrawn {when} · {n} location automations were turned off and will not run. Granting consent again does NOT turn them back on automatically — you re-enable each one. Manual control is unaffected.": "Dicabut {when} · {n} otomasi lokasi dinonaktifkan dan tidak akan berjalan. Memberikan persetujuan lagi TIDAK mengaktifkannya kembali secara otomatis — Anda mengaktifkan ulang satu per satu. Kontrol manual tidak terpengaruh.",
  "Withdrawn {when} · location automations cannot run until you grant it again. Manual control and schedules are unaffected.": "Dicabut {when} · otomasi lokasi tidak dapat berjalan sampai Anda memberikannya lagi. Kontrol manual dan jadwal tidak terpengaruh.",
  "Location automations need your consent. It is used only for arrival/departure automations — demo location events, no real GPS history.": "Otomasi lokasi memerlukan persetujuan Anda. Hanya dipakai untuk otomasi tiba/pergi — peristiwa lokasi demo, tanpa riwayat GPS nyata.",
