  "tech-external-a is on sick leave from today.": "tech-external-a cuti sakit mulai hari ini.",
  "On save, {current} loses action access immediately. The job keeps its state; {name} continues in a new draft version and the original report authorship is kept.": "Saat disimpan, {current} langsung kehilangan akses tindakan. Pekerjaan mempertahankan statusnya; {name} melanjutkan dalam versi draf baru dan kepenulisan laporan asli dipertahankan.",
