  "The technician could do {slot} instead — a different time needs the client’s approval via HQ.": "Teknisi dapat mengerjakan {slot} sebagai gantinya — waktu berbeda memerlukan persetujuan klien lewat HQ.",
  "No technician of your company can take this time (busy, unavailable or not qualified). Free a technician in Team & capacity, or ask HQ to agree another time with the client.": "Tidak ada teknisi perusahaan Anda yang dapat mengambil waktu ini (sibuk, tidak tersedia, atau tidak berkualifikasi). Bebaskan teknisi di Tim & kapasitas, atau minta HQ menyepakati waktu lain dengan klien.",
