  "Expired memberships ({names}) are listed but cannot be selected for assignment. A new access end is set in Users.": "Keanggotaan yang kedaluwarsa ({names}) dicantumkan tetapi tidak dapat dipilih untuk penugasan. Akhir akses baru ditetapkan di Pengguna.",
