  "Conflicts with {n} confirmed assignments: {list}. Saving keeps the assignments — reassign them in Schedule & assignments.": "Bentrok dengan {n} penugasan terkonfirmasi: {list}. Menyimpan mempertahankan penugasan — tugaskan ulang di Jadwal & penugasan.",
  "Unavailable days set the technician’s available hours to 0 for those dates, so utilization and the lists of who can take a visit skip them. For a public holiday of the whole team choose Public holiday and All technicians.": "Hari tidak tersedia mengatur jam tersedia teknisi menjadi 0 untuk tanggal tersebut, sehingga utilisasi dan daftar siapa yang dapat mengambil kunjungan melewatinya. Untuk hari libur nasional seluruh tim pilih Hari libur nasional dan Semua teknisi.",
