  "You said you can’t make this time (“{reason}”). Your coordinator reassigns the job or asks the client for another time.": "Anda menyatakan tidak bisa hadir pada waktu ini (“{reason}”). Koordinator Anda menugaskan ulang pekerjaan atau meminta klien memberi waktu lain.",
  "You said you can’t make this time. Your coordinator reassigns the job or asks the client for another time.": "Anda menyatakan tidak bisa hadir pada waktu ini. Koordinator Anda menugaskan ulang pekerjaan atau meminta klien memberi waktu lain.",
  "Start job (check in)": "Mulai pekerjaan (check-in)",
