  "The work window has ended — ask your coordinator to reschedule.": "Jendela pekerjaan telah berakhir — minta koordinator Anda menjadwalkan ulang.",
  "On site: Start job opens Check in (location + unit QR); checking in starts the work.": "Di lokasi: Mulai pekerjaan membuka Check-in (lokasi + QR unit); check-in memulai pekerjaan.",
  "On hold by HQ — saving and submitting are blocked. Your saved draft is kept; continue when HQ resumes the job.": "Ditahan oleh HQ — menyimpan dan menyerahkan diblokir. Draf tersimpan Anda dipertahankan; lanjutkan saat HQ melanjutkan pekerjaan.",
