  "The work window ended — unsaved input was discarded and the job can no longer be edited. Ask your coordinator.": "Jendela pekerjaan berakhir — masukan yang belum disimpan dibuang dan pekerjaan tidak dapat diubah lagi. Hubungi koordinator Anda.",
