  "Ask an identity administrator for Alert policies access.": "Minta administrator identitas untuk akses Kebijakan peringatan.",
  "Alert policies of {name}": "Kebijakan peringatan {name}",
  "Policies belong to the customer. Each unit picks which of them it carries (unit edit › Alert policies). Air-quality limits are alert policies too.": "Kebijakan milik pelanggan. Setiap unit memilih mana yang dibawanya (ubah unit › Kebijakan peringatan). Batas kualitas udara juga merupakan kebijakan peringatan.",
