  "Made by": "Dibuat oleh",
  "All {n}": "Semua {n}",
  "A row opens the policy editor (Alert policies › Policies). The default policy is on every unit; its rules can be switched per customer but it cannot be detached.": "Baris membuka editor kebijakan (Kebijakan peringatan › Kebijakan). Kebijakan default ada di setiap unit; aturannya dapat diaktifkan/dinonaktifkan per pelanggan tetapi tidak dapat dilepas.",
  "Default policy rules for {name}": "Aturan kebijakan default untuk {name}",
