  "Revoking sets “Valid until” to now and turns their sign-in off. Only HQ can give the access back — their company or customer cannot extend, enable or add them again. The membership stays listed; nothing is deleted.": "Mencabut mengatur “Berlaku sampai” ke sekarang dan mematikan akses masuk mereka. Hanya HQ yang dapat mengembalikan akses — perusahaan atau pelanggan mereka tidak dapat memperpanjang, mengaktifkan, atau menambahkannya lagi. Keanggotaan tetap tercantum; tidak ada yang dihapus.",
