  "Load command": "Muat perintah",
  "Links open the existing detail screens, and each checks your permission there. “Load command” reads the command only when you click it. Audit entries cannot be edited, deleted or exported.": "Tautan membuka layar detail yang ada, dan masing-masing memeriksa izin Anda di sana. “Muat perintah” membaca perintah hanya saat Anda mengkliknya. Entri audit tidak dapat diubah, dihapus, atau diekspor.",
  "You may not read this command — it needs control.execute, restriction.read, restriction.override or automation.policy.read.": "Anda tidak boleh membaca perintah ini — memerlukan control.execute, restriction.read, restriction.override, atau automation.policy.read.",
