  "No create, edit, or delete here — the log is append-only. Secrets and contacts in before/after are masked. Filters are kept in the URL; reasons and values never are.": "Tidak ada buat, ubah, atau hapus di sini — log bersifat tambah-saja. Rahasia dan kontak pada sebelum/sesudah disamarkan. Filter disimpan di URL; alasan dan nilai tidak pernah.",
  "No create, edit, or delete here. Secrets and contacts in before/after are masked. This browser demo does not guarantee tamper-proof storage.": "Tidak ada buat, ubah, atau hapus di sini. Rahasia dan kontak pada sebelum/sesudah disamarkan. Demo peramban ini tidak menjamin penyimpanan antipalsu.",
