  "Select a device…": "Pilih perangkat…",
  "The devices you may see. Events load only after you pick a device — there is no “all devices” view.": "Perangkat yang boleh Anda lihat. Peristiwa dimuat hanya setelah Anda memilih perangkat — tidak ada tampilan “semua perangkat”.",
