  "Choosing a role only pre-checks its typical permissions; every permission below stays editable. The client role is not offered here.": "Memilih peran hanya mencentang awal izin tipikalnya; setiap izin di bawah tetap dapat diubah. Peran klien tidak ditawarkan di sini.",
  "Write includes Read (Read is locked on while Write is on). Actions are independent of Read/Write — e.g. billing.write issues invoices but confirming payments needs billing.payment; mrv.write drafts reports but recording a review needs mrv.review and changing emission factors needs mrv.factors.": "Tulis mencakup Baca (Baca terkunci aktif selama Tulis aktif). Tindakan independen dari Baca/Tulis — mis. billing.write menerbitkan faktur tetapi mengonfirmasi pembayaran memerlukan billing.payment; mrv.write menyusun laporan tetapi mencatat tinjauan memerlukan mrv.review dan mengubah faktor emisi memerlukan mrv.factors.",
