  "Related restrictions": "Pembatasan terkait",
  "This invoice is a cause of this restriction. Once all of its cause invoices are paid, it moves to “release requested”. Its state and units are on the Restrictions screen (restriction.read).": "Faktur ini adalah penyebab pembatasan ini. Setelah semua faktur penyebabnya dibayar, pembatasan berpindah ke “pencabutan diminta”. Status dan unitnya ada di layar Pembatasan (restriction.read).",
  "This invoice is a cause of these restrictions. Once all cause invoices of a restriction are paid, it moves to “release requested”. Their states and units are on the Restrictions screen (restriction.read).": "Faktur ini adalah penyebab pembatasan-pembatasan ini. Setelah semua faktur penyebab sebuah pembatasan dibayar, pembatasan berpindah ke “pencabutan diminta”. Status dan unitnya ada di layar Pembatasan (restriction.read).",
