  "A job assigned to this technician that has not started is released and returns to be assigned; its assigners are notified.": "Pekerjaan yang ditugaskan kepada teknisi ini yang belum dimulai dilepas dan kembali untuk ditugaskan; penugasnya diberi tahu.",
